/*
 * Cloudflare Worker proxy used when CF_PROXY_URL is configured.
 * Replace refresh_token with the one generated by the Colab notebook.
 */
var credentials = {
  "client_id": "202264815644.apps.googleusercontent.com", // rclone client_id
  "client_secret": "X4Z3ca8xfWDb1Voo-F9a7ZxJ", // rclone client_secret
  "refresh_token": "*******", // refresh token is unique
  "token": null
}

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS"
}

function jsonResponse(body, status) {
  return new Response(JSON.stringify(body), {
    status: status,
    headers: Object.assign({}, CORS_HEADERS, { "Content-Type": "application/json" })
  })
}

async function handleRequest(request, event) {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS })
  }

  const url = new URL(request.url)
  const path_split = url.pathname.split("/").filter(Boolean)

  if (url.pathname === "/") {
    return new Response("200 Online!", { status: 200, headers: CORS_HEADERS })
  }

  if (path_split[0] === "load" && path_split[1]) {
    const file_id = decodeURIComponent(path_split[1])
    const file_name = path_split[2] ? decodeURIComponent(path_split[2]) : "file_name.vid"
    try {
      const drive = new gdrive(credentials)
      return await drive.streamFile(request.headers.get("Range"), file_id, event)
    } catch (err) {
      return jsonResponse({ error: String(err) }, 502)
    }
  }

  return new Response("404 Not Found!", { status: 404, headers: CORS_HEADERS })
}

class gdrive {
  constructor(credentials) {
    this.gapihost = "https://www.googleapis.com"
    this.credentials = credentials
  }

  async streamFile(range, file_id, event) {
    const fetchURL = `${this.gapihost}/drive/v3/files/${encodeURIComponent(file_id)}?alt=media`
    const fetchData = await this.authData()

    // Sending `Range: null` makes Google reject the request with a 416.
    if (range) fetchData.headers["Range"] = range

    const streamResp = await fetch(fetchURL, fetchData)
    if (!streamResp.ok && streamResp.status !== 206) {
      return new Response(streamResp.body, {
        status: streamResp.status,
        statusText: streamResp.statusText,
        headers: Object.assign({}, CORS_HEADERS)
      })
    }

    const { readable, writable } = new TransformStream()
    const pipe = streamResp.body.pipeTo(writable)
    if (event && typeof event.waitUntil === "function") event.waitUntil(pipe)

    const headers = new Headers(streamResp.headers)
    Object.keys(CORS_HEADERS).forEach(key => headers.set(key, CORS_HEADERS[key]))
    return new Response(readable, {
      status: streamResp.status,
      statusText: streamResp.statusText,
      headers: headers
    })
  }

  async accessToken() {
    if (!this.credentials.token || this.credentials.token.expires_at < Date.now()) {
      this.credentials.token = await this.fetchAccessToken()
      this.credentials.token.expires_at =
        Date.now() + Number(this.credentials.token.expires_in || 3600) * 1000
    }
    return this.credentials.token.access_token
  }

  async fetchAccessToken() {
    const jsonBody = {
      "client_id": this.credentials.client_id,
      "client_secret": this.credentials.client_secret,
      "refresh_token": this.credentials.refresh_token,
      "grant_type": "refresh_token"
    }
    const response = await fetch("https://oauth2.googleapis.com/token", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(jsonBody)
    })
    const data = await response.json()
    if (!data || !data.access_token) {
      throw new Error("Could not refresh Google Drive access token: " + JSON.stringify(data))
    }
    return data
  }

  async authData(headers = {}) {
    headers["Authorization"] = `Bearer ${await this.accessToken()}`
    return { "method": "GET", "headers": headers, "redirect": "follow" }
  }
}

addEventListener("fetch", (event) => {
  event.respondWith(handleRequest(event.request, event))
})
